function pb.evidence(Vo,Wo,Xo)
local Yo=type(Xo.nums)==nHe[2232]and Xo.nums or{}
local Zo=Vo.firstPlaced[Wo]
if not Zo then
return{why=nHe[2638]}
end
local _o={}
for ap,bp in ipairs(Xo.buffs or{})do
_o[bp]=true
end
local function cp(dp)
if#dp==0 then
return nil
end
table.sort(dp)
return dp[math.ceil(#dp/2)]
end
if Xo.family==nHe[2426]then
if(Vo.sales or 0)==0 then
return{why=nHe[2639]}
end
local ep,fp
for ip in pairs(Vo.own)do
local jp,kp,lp,mp,np=0,0,0,0,0
for op,pp in pairs(Vo.copies)do
local qp=pp.buff[ip]or 0
if(pp.sold or 0)>0 then
if pp.id~=Wo then
mp=mp+1
end
if qp>0 then
if pp.id==Wo then
jp=jp+1
else
lp=lp+1
end
np=math.max(np,qp)
end
elseif qp>0 then
kp=kp+1
end
end
if jp>0 and kp==0 and(not fp or jp>fp)then
ep,fp={name=ip,other=lp,otherAfter=mp,top=np},jp
end
end
if not ep then
return{why=nHe[2640]}
end
local rp=(ep.other>0 and nHe[1162])or(ep.otherAfter>0 and nHe[2641])or nHe[2642]
return{seen=true,buff=ep.name,who=rp,nums={stacks=(Vo.sales>1 and ep.top>1)or nil,sales=Vo.sales},why=string.format(nHe[2643],fp,ep.name,rp==nHe[2641]and nHe[2644]or nHe[1151])}
end
local vp=Xo.trigger and tostring(Xo.trigger):find(nHe[2645],1,true)~=nil
local wp=0
for yp,zp in ipairs(Vo.casts)do
if zp.id==Wo then
wp=wp+1
end
end
if vp and wp==0 and(Xo.family==nHe[2427]or Xo.family==nHe[2424])then
return{why=nHe[2646]}
end
if Xo.family==nHe[2427]then
local Ap,Bp,Cp
for Dp,Ep in pairs(Vo.own)do
if Ep.first>=Zo-1 and(_o[Dp]or Ep.first<=Zo+5 or vp)and(not vp or pb.nearCast(Vo,Wo,Ep.starts)>0)then
local Fp=0
for Gp,Hp in pairs(Ep.by)do
if Gp~=Wo then
Fp=Fp+Hp
end
end
if Fp>0 and(not Ap or(_o[Dp]and not Cp)or((_o[Dp]or false)==(Cp or false)and Fp>Bp))then
Ap,Bp,Cp=Dp,Fp,_o[Dp]
end
end
