if not Ap then
return{why=nHe[2647]}
end
return{seen=true,buff=Ap,why=string.format(nHe[2648],Ap)}
end
if Xo.family==nHe[2424]then
local Ip,Jp
for Kp,Lp in pairs(Vo.foeBuffs)do
if Lp.first>=Zo-1 and Lp.near>0 and(_o[Kp]or Lp.near>=0.5*Lp.n)and(not vp or pb.nearCast(Vo,Wo,Lp.onsets)>0)then
local Mp=Lp.near+(_o[Kp]and 1e6 or 0)+(vp and pb.nearCast(Vo,Wo,Lp.onsets)*1000 or 0)
if not Jp or Mp>Jp then
Ip,Jp=Kp,Mp
