if Xo.family==nHe[2428]then
local pq,qq
for rq,sq in pairs(Vo.own)do
if(sq.by[Wo]or 0)>0 and sq.first>=Zo-1 and(not pq or(_o[rq]and not _o[pq]))then
pq,qq=rq,sq
