end
local tq
for uq,vq in ipairs(Vo.transforms)do
if vq.from==Wo then
tq=vq.to
end
end
if not pq then
local wq,xq,yq
for zq,Aq in pairs(Vo.copies)do
if Aq.id==Wo or(tq and Aq.id==tq)then
for Bq,Cq in pairs(Aq.stat or{})do
if Cq.hi>Cq.lo and(not wq or(Cq.hi-Cq.lo)>(yq-xq))then
wq,xq,yq=Bq,Cq.lo,Cq.hi
end
end
end
end
if not wq then
return{why=nHe[2656]}
end
return{seen=true,nums={stat=wq,loSeen=xq,hiSeen=yq,transformTo=tq},why=string.format(nHe[2657],wq,tostring(xq),tostring(yq))}
end
