if vs and vs.kind==nHe[2414]and not(type(js.shred)==nHe[2232])then
local As=tonumber(js.amp)
local Bs=Sr and((type(Sr.ampTypes)==nHe[2232]and Sr.ampTypes[vs.dtype])or(tonumber(Sr.amp)or 0)>0)
if As and As>0 and not Bs then
Wr.fx,Xr=(Wr.fx or 0)+As*V.TYPED_AMP_SHARE*zs*Zr,true
end
elseif vs and(vs.kind==nHe[2361]or vs.kind==nHe[2422])then
if not(Sr and((tonumber(Sr.stun)or 0)>0 or(tonumber(Sr.slowTime)or 0)>0))then
