end
if type(js.ampFrom)==nHe[2232]and tostring(js.ampFrom.kind)==nHe[2074]and(tonumber(js.ampFrom.amp)or 0)>0 then
local Es=(type(js.secsBy)==nHe[2232]and#js.secsBy>0)and js.secsBy or{tonumber(js.secsSeen)or tonumber(js.secs)or 5}
