function mb.weatherStrength(pE)
local qE=mb.fx(pE)
local rE=qE.dmg/qE.cd/qE.hp/qE.speed*(1+(qE.range-1)/2)
for sE,tE in pairs(qE.kinds)do
rE=rE*(1+bb.rogueShare(sE)*tE)
end
if qE.ice>0 then
local uE=bb.rogueShare(nHe[2377])
rE=rE*(uE+(1-uE)/(1-qE.ice+qE.ice/gb.modFactor(nHe[2784])))
end
if qE.fly>0 then
rE=rE*(1-qE.fly*0.5)
end
if qE.noCC then
rE=rE*0.95
end
if qE.shroud then
rE=rE*0.9
end
if qE.zap then
rE=rE*0.85
end
return rE/mb.weatherK(pE)
end
mb.WEATHER_K_MIN,mb.WEATHER_K_MAX,mb.WEATHER_K_RUNS=0.5,4,10
function mb.weatherK(vE)
local wE=vE and type(P.hunt)==nHe[2232]and type(P.hunt.wk)==nHe[2232]and P.hunt.wk[tostring(vE)]or nil
return type(wE)==nHe[2232]and tonumber(wE.k)or 1
end
function mb.weatherLearn()
if bb.withOthers or#game:GetService(nHe[1130]):GetPlayers()>1 then
return
end
local xE=bb.huntWeather or mb.weatherNow()
local yE,zE=bb.pred,bb.calRun
if not xE or type(yE)~=nHe[2232]or type(zE)~=nHe[2232]then
return
end
