return type(BE)==nHe[2232]and tonumber(BE[CE]or BE[tostring(CE)])or nil
end
local DE={}
for EE=2,bb.wave()do
local FE,GE=AE(zE.alive,EE),AE(yE.aliveAt,EE)
if FE and GE and FE>0 and GE>0 then
table.insert(DE,FE/GE)
end
end
if#DE<3 then
return
end
table.sort(DE)
local HE=DE[math.ceil(#DE/2)]
P.hunt.wk=type(P.hunt.wk)==nHe[2232]and P.hunt.wk or{}
