local ME=math.exp((LE*math.log(KE)+math.log(KE*HE))/(LE+1))
ME=U.clamp(ME,mb.WEATHER_K_MIN,mb.WEATHER_K_MAX)
bb.wkWas={w=tostring(xE),old=IE}
P.hunt.wk[tostring(xE)]={k=ME,n=(type(IE)==nHe[2232]and tonumber(IE.n)or 0)+1,at=os.time()}
F.log(1,nHe[2785],string.format(nHe[2786],tostring(xE),HE,tostring(xE),ME,KE,P.hunt.wk[tostring(xE)].n))
end
