if Jab and Jab.item_group==nHe[1085]then
local Kab=type(Iab._unique_item_data)==nHe[2232]and Iab._unique_item_data._unique_defense_data or{}
table.insert(Fab,{uuid=Iab.uuid,item_id=Iab.item_id,g=tonumber(Kab.g)or 0,d=tonumber(Kab.d),equipped=tonumber(Kab._e)~=nil})
Gab[Iab.item_id]=(Gab[Iab.item_id]or 0)+1
end
