end
local Uab
for Vab,Wab in ipairs(Lab or{})do
local Xab=type(Wab)==nHe[2232]and ab.DEF_WANT[Wab.item_id]
local Yab=type(Wab)==nHe[2232]and tonumber(Wab.price)or nil
if Xab and Yab and Yab<=Sab then
local Zab=Oab[Wab.item_id]or 0
if Pab<Rab or Zab==0 then
if not Uab or Zab<Uab.have or(Zab==Uab.have and Xab<Uab.pr)then
Uab={index=Vab,item_id=Wab.item_id,price=Yab,have=Zab,pr=Xab}
end
end
end
end
return Uab
end
function ab.defEquipPlan(_ab,abb)
local bbb,cbb,dbb=0,{},{}
for ebb,fbb in ipairs(_ab)do
if fbb.equipped then
bbb=bbb+1
cbb[fbb.item_id]=true
elseif ab.DEF_WANT[fbb.item_id]and(fbb.d==nil or fbb.d>0)then
table.insert(dbb,fbb)
end
end
local gbb={}
while bbb+ #gbb<abb and#dbb>0 do
table.sort(dbb,function(hbb,ibb)
local jbb,kbb=cbb[hbb.item_id]and 1 or 0,cbb[ibb.item_id]and 1 or 0
if jbb~=kbb then
return jbb<kbb
end
if ab.DEF_WANT[hbb.item_id]~=ab.DEF_WANT[ibb.item_id]then
return ab.DEF_WANT[hbb.item_id]<ab.DEF_WANT[ibb.item_id]
end
return hbb.g>ibb.g
end)
local lbb=table.remove(dbb,1)
cbb[lbb.item_id]=true
table.insert(gbb,lbb)
end
return gbb
end
