return Adb
end
function kb.gainXp(_db,aeb)
local beb,ceb=tonumber(_db.xp)or 0,kb.xpFor(_db.unit_id,kb.cap(_db))
local deb=math.max(0,ceb-beb)
if deb<=0 or(aeb or 0)<=0 then
return 0,0
end
local eeb=math.min(aeb,deb)
local feb=kb.base(_db)
if feb<=0 then
return 0,eeb
end
return kb.share(_db.unit_id)*(kb.score(kb.whatIf(_db,{xp=beb+eeb}))/feb-1)*100,eeb
end
