end
function kb.relicWorth(geb,heb)
local ieb=heb._unique_item_data and heb._unique_item_data._unique_relic_data
if not ieb then
return 0
end
local jeb=N.Items[heb.item_id]or{}
local keb,leb=V.types(geb.unit_id)
if jeb.main_damage_type and jeb.main_damage_type~=nHe[2928]and jeb.main_damage_type~=leb then
return 0
end
local meb,neb=0,0
for oeb,peb in pairs(ieb._core_damage_type_buffs or{})do
if keb[peb.damage_type]then
meb=meb+(tonumber(peb.mul)or 0)+(tonumber(peb.add_upg)or 0)*0.01+(tonumber(peb.pen)or 0)*0.001
neb=neb+(tonumber(peb.crit)or 0)
end
end
meb=meb+neb*0.5
local qeb=V.rows(geb.unit_id)
local reb=qeb and qeb[qeb.max]
local seb=(reb and tonumber(reb.cd)or 0)*V.mult(geb,nHe[2678])
for teb,ueb in pairs(ieb._unique_relic_effects or{})do
local veb=type(ueb.params)==nHe[2232]and ueb.params or{}
if ueb.id==nHe[3330]then
local web=math.min(1,(tonumber(veb.extra_damage)or 0)*seb/math.max(1,tonumber(veb.time_interval)or 40))
local xeb=V.DRONES and V.DRONES[geb.unit_id]
if xeb and xeb.late and seb>0 then
local yeb=1/seb
web=web*yeb/(yeb+(tonumber(xeb.max)or 0)*(tonumber(xeb.late.dmg)or 0)*(tonumber(xeb.hits)or 1)/math.max(0.1,tonumber(xeb.late.cd)or 4))
end
meb=meb+web
elseif ueb.id==nHe[3331]then
meb=meb+(tonumber(veb.dmg_buff)or 0)*0.25
elseif ueb.id==nHe[3332]then
meb=meb+(tonumber(veb.dmg_buff)or 0)*neb
elseif ueb.id==nHe[3333]then
if keb.magic then
meb=0
else
meb=meb+(tonumber(veb.dmg_buff)or 0)*0.3
end
elseif ueb.id==nHe[3334]then
if keb.water_damage then
meb=meb+0.05
end
elseif ueb.id==nHe[2378]then
local zeb=tonumber(veb.duration_buff)or tonumber(type(ueb.static_params)==nHe[2232]and ueb.static_params.duration_buff)or 2
local Aeb,Beb=pcall(V.attackInfo,reb and reb.atk,reb and reb.range)
local Ceb,Deb=Aeb and tonumber(Beb.burn)or 0,Aeb and tonumber(Beb.dot)or 0
if Ceb<=0 then
local Eeb,Feb=pcall(pb.model,geb.unit_id,Aeb and Beb or nil,reb)
if Eeb and type(Feb)==nHe[2232]and(tonumber(Feb.burnDot)or 0)>0 then
Ceb,Deb=Feb.burnDot,Deb+(tonumber(Feb.dot)or 0)
end
end
meb=meb+Ceb*math.max(0,zeb-1)/(1+Deb)
end
end
return meb
end
function kb.relicPlan()
local Geb=N.session()
if not Geb then
return nil
end
local Heb=Geb.inventory and Geb.inventory.inventory_profile_data or{}
local Ieb={}
for Jeb,Keb in ipairs(Heb.unique_items or{})do
if type(Keb)==nHe[2232]and Keb.uuid and(N.Items[Keb.item_id]or{}).item_group==nHe[3266]then
table.insert(Ieb,Keb)
end
end
local Leb={}
for Meb,Neb in ipairs(V.equipped())do
local Oeb=Neb.data and Neb.data.rarity
if not V.isFarm(Neb.id)and(Oeb==nHe[2815]or Oeb==nHe[2816]or Oeb==nHe[3328]or Oeb==nHe[3335])then
local Peb=kb.share(Neb.id)
if not P.str.share[Neb.id]then
Peb=math.min(Peb,0.15)
end
local Qeb={}
for Reb,Seb in ipairs(Ieb)do
local Teb=kb.relicWorth(Neb.u,Seb)*Peb*100
if Teb>0.01 then
table.insert(Qeb,{it=Seb,w=Teb})
end
end
table.sort(Qeb,function(Ueb,Veb)
if Ueb.w~=Veb.w then
return Ueb.w>Veb.w
end
return Ueb.it.uuid<Veb.it.uuid
end)
local Web,Xeb={},{}
for Yeb,Zeb in ipairs(Qeb)do
local _eb=Xeb[Zeb.it.item_id]or 0
if#Web<6 and _eb<((N.Items[Zeb.it.item_id]or{}).unique_equip and 1 or 2)then
Xeb[Zeb.it.item_id]=_eb+1
table.insert(Web,Zeb)
end
end
if Neb.u._equipped_relic then
local afb=false
for bfb,cfb in ipairs(Web)do
if cfb.it.uuid==Neb.u._equipped_relic then
afb=true
end
end
local dfb=not afb and Geb.inventory:get_item_by_uuid(Neb.u._equipped_relic)
if dfb then
table.insert(Web,{it=dfb,w=kb.relicWorth(Neb.u,dfb)*Peb*100})
end
end
table.insert(Leb,{e=Neb,share=Peb,opts=Web})
end
end
local efb,ffb={},-1
local gfb,hfb,ifb={},{},{}
local function jfb(kfb,lfb)
if kfb> #Leb then
if lfb>ffb then
ffb=lfb
efb=table.clone(gfb)
end
return
end
local mfb=Leb[kfb]
gfb[mfb.e.uuid]=nil
jfb(kfb+1,lfb)
for nfb,ofb in ipairs(mfb.opts)do
local pfb=(N.Items[ofb.it.item_id]or{}).unique_equip
if not hfb[ofb.it.uuid]and not(pfb and ifb[ofb.it.item_id])then
hfb[ofb.it.uuid]=true
if pfb then
ifb[ofb.it.item_id]=true
end
gfb[mfb.e.uuid]=ofb.it.uuid
jfb(kfb+1,lfb+ofb.w+(ofb.it.uuid==mfb.e.u._equipped_relic and 0.01 or 0))
gfb[mfb.e.uuid]=nil
hfb[ofb.it.uuid]=nil
if pfb then
ifb[ofb.it.item_id]=nil
end
end
end
end
jfb(1,0)
local qfb,rfb=0,{}
for sfb,tfb in ipairs(Leb)do
local ufb=tfb.e.u._equipped_relic and Geb.inventory:get_item_by_uuid(tfb.e.u._equipped_relic)
local vfb=ufb and kb.relicWorth(tfb.e.u,ufb)*tfb.share*100 or 0
qfb=qfb+vfb
local wfb=efb[tfb.e.uuid]and Geb.inventory:get_item_by_uuid(efb[tfb.e.uuid])
local xfb=wfb and kb.relicWorth(tfb.e.u,wfb)*tfb.share*100 or 0
table.insert(rfb,string.format(nHe[3336],V.name(tfb.e.id),ufb and(N.Items[ufb.item_id]or{}).name or nHe[2826],vfb,wfb and(N.Items[wfb.item_id]or{}).name or nHe[2826],xfb))
end
return efb,ffb-qfb,rfb,Leb
end
