local zkb={[wkb.uuid]=true,[O.evolveUnit]=true}
for Akb,Bkb in ipairs(V.equipped())do
zkb[Bkb.uuid]=true
end
for Ckb,Dkb in ipairs(P.savedTeam or{})do
zkb[Dkb]=true
end
for Ekb,Fkb in ipairs(P.train and P.train.on and P.train.on.base or{})do
zkb[Fkb]=true
end
local Gkb={}
local function Hkb(Ikb)
local Jkb=Ikb and N.Units[Ikb.unit_id]
local Kkb=Jkb and Jkb.evolve and(Ikb.shiny and Jkb.evolve.shiny or Jkb.evolve.normal)
for Lkb,Mkb in pairs(type(Kkb)==nHe[2232]and type(Kkb.unit_requirement)==nHe[2232]and Kkb.unit_requirement or{})do
if type(Mkb)==nHe[2232]and Mkb.unit_id then
Gkb[Mkb.unit_id]=math.max(Gkb[Mkb.unit_id]or 0,tonumber(Mkb.amount)or 1)
end
end
end
pcall(Hkb,wkb)
pcall(function()
