local Skb=Rkb and ab.FUSE_RANK[Rkb.rarity]
if Skb and Skb<=ykb and not zkb[Pkb]and(Gkb[Qkb.unit_id]or 0)>0 then
Gkb[Qkb.unit_id]=Gkb[Qkb.unit_id]-1
Skb=nil
end
if Skb and Skb<=ykb and not zkb[Pkb]then
local Tkb=xkb.collection:get_unit_by_uuid(Pkb)or Qkb
if not(Qkb._locked or Tkb._locked)and not(Qkb._equipped_relic or Tkb._equipped_relic)then
local Ukb,Vkb=pcall(N.USC.calculate_xp_gain_from_fuse,wkb,{Tkb},xkb)
Vkb=Ukb and tonumber(Vkb)or 0
if Vkb>0 then
table.insert(Nkb,{uuid=Pkb,id=Qkb.unit_id,xp=Vkb,rarity=Rkb.rarity})
Okb=Okb+Vkb
end
end
end
end
table.sort(Nkb,function(Wkb,Xkb)
if Wkb.xp~=Xkb.xp then
return Wkb.xp<Xkb.xp
end
return Wkb.uuid<Xkb.uuid
end)
local Ykb=math.max(0,kb.xpFor(wkb.unit_id,kb.cap(wkb))-(tonumber(wkb.xp)or 0))
local Zkb,_kb={},0
