function ab.worldSkip()
if F.where~=nHe[2312]or not O.worldSkip or not(O.firstClears or O.onlyStory)then
return
end
local hyb=N.WLO and N.WLO.SKIPPABLE_WORLDS
if type(hyb)~=nHe[2232]then
return
end
local iyb=(N.prof()or{}).level_data or{}
local jyb,kyb,lyb
for myb,nyb in ipairs(U.list(N.WLO.WORLD_ORDER))do
local oyb=N.Worlds[nyb]
if oyb and not oyb.legend_stage and not oyb.raid_world then
local pyb=U.list(oyb.levels)
local qyb=pyb[#pyb]
if qyb and not W.done(iyb,qyb.id,nHe[1156])then
jyb,kyb,lyb=nyb,pyb[1],qyb
break
end
end
end
if not(jyb and hyb[jyb]and kyb and lyb)then
return
end
if W.open(lyb.id)or not W.open(kyb.id)then
return
end
P.worldSkip=type(P.worldSkip)==nHe[2232]and P.worldSkip or{}
local ryb=P.worldSkip[jyb]
if type(ryb)==nHe[2232]and(ryb.done or os.time()-(tonumber(ryb.at)or 0)<ab.WORLD_SKIP_RETRY)then
return
end
local syb=N.Worlds[jyb]
local tyb=tostring(syb and syb.name or jyb)
local uyb={key=nHe[2952]..lyb.id..nHe[3060],kind=nHe[2280],first=true,level=lyb.id,diff=nHe[1156],label=W.levelName(lyb.id)..nHe[3061]}
local vyb,wyb=pcall(gb.plan,uyb,false)
if not(vyb and type(wyb)==nHe[2232])then
