for yyb,zyb in ipairs(U.list(syb.levels))do
xyb[zyb.id]=W.done(iyb,zyb.id,nHe[1156])
end
local Ayb=U.now()
F.log(1,nHe[2866],string.format(nHe[3737],tyb,W.levelName(lyb.id),tostring(wyb.margin)))
local Byb,Cyb=F.request(nHe[3738],nHe[3739],jyb)
local Dyb=false
while U.now()-Ayb<8 do
task.wait(1)
if W.open(lyb.id)then
Dyb=true
break
end
end
local Eyb=F.gameSaid(Ayb)
P.worldSkip[jyb]={at=os.time(),done=Dyb or nil,last=lyb.id,said=Eyb and tostring(Eyb):sub(1,80)or nil}
F.saveSoon()
if Dyb then
local Fyb=(N.prof()or{}).level_data or{}
local Gyb={}
for Hyb,Iyb in ipairs(U.list(syb.levels))do
if Iyb.id~=lyb.id and not xyb[Iyb.id]and W.done(Fyb,Iyb.id,nHe[1156])then
table.insert(Gyb,W.levelName(Iyb.id))
end
end
F.log(1,nHe[2866],string.format(nHe[3740],tyb,#Gyb>0 and(nHe[3741]..table.concat(Gyb,nHe[2356]))or nHe[3742],Eyb and(nHe[3743]..tostring(Eyb))or nHe[1151]))
W.lastScored=nil
else
F.log(1,nHe[2866],string.format(nHe[3744],tyb,tostring(Eyb or(Byb and Cyb)or nHe[2779])))
end
end
