if V.isFarm(Ajc.unit_id)then
local Bjc=table.clone(Sic)
Bjc[yjc]=Ajc
local Cjc=gb.run(Nic,gb.teamFrom(Bjc,Nic.map),{hpMul=Yic})
local Djc=gb.objective(Cjc)
if not xjc or Djc>xjc then
wjc,xjc,kjc=Bjc,Djc,Cjc
end
end
end
end
if wjc then
Sic=wjc
end
