if not Ljc or Pjc<Ljc then
Kjc,Ljc=Mjc,Pjc
end
end
end
if Kjc then
local Qjc,Rjc={},U.now()
for Sjc,Tjc in ipairs(Pic.rest)do
if U.now()-Rjc>5 then
break
end
local Ujc=false
for Vjc,Wjc in ipairs(Sic)do
if V.sameGroup(Wjc.unit_id,Tjc.unit_id)then
Ujc=true
end
end
if not Ujc then
local Xjc=table.clone(Sic)
Xjc[Kjc]=Tjc
