end)
Pic=table.clone(Pic)
for _jc=1,math.min(4,#Qjc)do
table.insert(Pic,1,Qjc[_jc].u)
end
Ric=Ric+(U.now()-Rjc)
end
end
for akc=1,2 do
local bkc=false
for ckc=1,#Sic do
