end
end
if Sic[ckc]and Sic[ckc].unit_id==ekc.unit_id then
fkc=true
end
if not fkc then
local ikc=table.clone(Sic)
ikc[ckc]=ekc
if(not ejc or _ic(ikc)>0)and fjc(ikc)>=math.min(8,fjc(Sic))then
