elseif mqc.type==nHe[4285]and mqc.stat==nHe[4286]then
iqc=iqc+60*nqc*jb.share(nHe[2417])
elseif mqc.type==nHe[4287]then
iqc=iqc+40*nqc
elseif mqc.type==nHe[4288]then
iqc=iqc+80*nqc
elseif mqc.type==nHe[4289]then
iqc=iqc+80*nqc
