if not qzc then
return
end
for rzc,szc in pairs(qzc)do
if not(N.PATH.HIDDEN_MOCK_LANES and N.PATH.HIDDEN_MOCK_LANES[rzc.Name])then
local tzc={}
for uzc,vzc in ipairs(szc.points or{})do
table.insert(tzc,vzc.part.Position)
end
local wzc=0
for xzc=2,#tzc do
wzc=wzc+(tzc[xzc]-tzc[xzc-1]).Magnitude
end
local yzc=0
for zzc=2,#tzc do
local Azc,Bzc=tzc[zzc-1],tzc[zzc]
local Czc=(Bzc-Azc).Magnitude
local Dzc=math.max(1,math.floor(Czc/2))
for Ezc=0,Dzc-1 do
local Fzc=Azc:Lerp(Bzc,Ezc/Dzc)
table.insert(bb.samples,{pos=Fzc,prog=(yzc+Czc*Ezc/Dzc)/math.max(1,wzc),lane=rzc.Name})
end
yzc=yzc+Czc
end
if tzc[#tzc]then
table.insert(bb.samples,{pos=tzc[#tzc],prog=1,lane=rzc.Name})
end
end
end
pcall(bb.readHidden,qzc)
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
local Gzc=tonumber(bb.ld and bb.ld._portal_lanes)
local Hzc=gb.laneList(bb.samples)
if Gzc and Gzc>=1 and Hzc and#Hzc>Gzc then
