function bb.readHidden(Izc)
local Jzc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(Jzc)~=nHe[2232]or not next(Jzc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
return
end
local Kzc
for Lzc,Mzc in pairs(Izc)do
if Jzc[Lzc.Name]and type(Mzc.points)==nHe[2232]and#Mzc.points>=2 then
local Nzc={}
for Ozc,Pzc in ipairs(Mzc.points)do
Nzc[Ozc]=U.flat(Pzc.part.Position)
end
local Qzc={}
for Rzc,Szc in ipairs(bb.samples)do
local Tzc=tostring(Szc.lane)
Qzc[Tzc]=Qzc[Tzc]or{}
table.insert(Qzc[Tzc],Szc)
end
local Uzc,Vzc
for Wzc,Xzc in pairs(Qzc)do
local Yzc=0
for Zzc=1,#Nzc,math.max(1,math.floor(#Nzc/20))do
local _zc=math.huge
for aAc,bAc in ipairs(Xzc)do
local cAc=(U.flat(bAc.pos)-Nzc[Zzc]).Magnitude
if cAc<_zc then
_zc=cAc
end
end
Yzc=Yzc+_zc
end
if not Vzc or Yzc<Vzc then
Uzc,Vzc=Wzc,Yzc
end
end
local dAc,eAc,fAc,gAc,hAc,iAc={},nil,nil,nil,0,0
for jAc,kAc in ipairs(Nzc)do
local lAc,mAc=nil,math.huge
for nAc,oAc in ipairs(Qzc[Uzc])do
local pAc=(U.flat(oAc.pos)-kAc).Magnitude
if pAc<mAc then
mAc,lAc=pAc,oAc.prog
end
end
iAc=math.max(iAc,mAc)
if fAc then
local qAc=lAc-fAc
local rAc=(qAc>0.002 and 1)or(qAc< -0.002 and-1)or gAc
if gAc and rAc and rAc~=gAc then
table.insert(dAc,math.floor(fAc*1000+0.5)/1000)
end
gAc,hAc=rAc or gAc,hAc+math.abs(qAc)
else
eAc=lAc
end
fAc=lAc
if jAc%50==0 then
task.wait()
end
end
if fAc and iAc<=8 then
table.insert(dAc,math.floor(fAc*1000+0.5)/1000)
Kzc=Kzc or{}
Kzc[Lzc.Name]={from=math.floor((eAc or 0)*1000+0.5)/1000,len=math.floor(hAc*1000+0.5)/1000,turns=dAc,road=Uzc}
end
end
end
if not Kzc then
return
end
local sAc=bb.ld.map
P.maps[sAc]=P.maps[sAc]or{}
local tAc=P.maps[sAc].hidden
P.maps[sAc].hidden=Kzc
if type(tAc)~=nHe[2232]then
for uAc,vAc in pairs(Kzc)do
F.log(1,nHe[2913],string.format(nHe[4445],uAc,vAc.len,tostring(vAc.road),math.floor((#vAc.turns-1)/2)))
end
F.saveSoon()
end
end
