if eEc.Magnitude<0.01 then
eEc=Vector3 .new(1,0,0)
end
eEc=eEc.Unit
local fEc=Vector3 .new(-eEc.Z,0,eEc.X)
for gEc,hEc in ipairs({3,4.5,6,8,10.5,13.5,17})do
for iEc,jEc in ipairs({1,-1})do
local kEc=cEc.pos+fEc*hEc*jEc
local lEc=string.format(nHe[4478],math.floor(kEc.X/1.5),math.floor(kEc.Z/1.5))
if not aEc[lEc]then
aEc[lEc]=true
table.insert(bb.cands,kEc)
end
end
