function bb.coverage(mEc,nEc)
local oEc={}
for pEc,qEc in ipairs(mEc)do
local rEc=qEc._stats
if not V.isFarm(rEc.id.Value)and rEc:FindFirstChild(nHe[2495])then
table.insert(oEc,{p=U.flat(qEc:GetPivot().Position),r=rEc.range.Value*(V.SUMMONER[rEc.id.Value]and V.SUMMONER[rEc.id.Value].reach or 1),air=bb.canAir(qEc)})
end
end
local sEc,tEc=0,0
if#oEc>0 then
for uEc,vEc in ipairs(bb.samples)do
if vEc.prog>tEc then
local wEc=U.flat(vEc.pos)
for xEc,yEc in ipairs(oEc)do
if(wEc-yEc.p).Magnitude<=yEc.r then
if vEc.prog>sEc then
sEc=vEc.prog
end
if yEc.air then
tEc=vEc.prog
break
end
end
end
end
end
end
local zEc,AEc={},bb.laneCount
if AEc and AEc.n>=2 and#oEc>0 then
local BEc={}
for CEc,DEc in ipairs(bb.samples)do
local EEc=U.flat(DEc.pos)
for FEc,GEc in ipairs(oEc)do
if(EEc-GEc.p).Magnitude<=GEc.r then
local HEc=tostring(DEc.lane)
BEc[HEc]=(BEc[HEc]or 0)+1
if DEc.prog>(zEc[HEc]or 0)then
zEc[HEc]=DEc.prog
end
break
end
end
end
local IEc,JEc={},0
for KEc,LEc in pairs(AEc.by)do
IEc[KEc]=(BEc[KEc]or 0)/math.max(1,LEc)
JEc=math.max(JEc,IEc[KEc])
end
bb.laneW={}
for MEc,NEc in pairs(AEc.by)do
bb.laneW[MEc]=(AEc.avg/math.max(1,NEc))*(1+1.5*(JEc>0 and(1-IEc[MEc]/JEc)or 0))
end
bb.laneFrac=IEc
else
bb.laneW,bb.laneFrac=nil,nil
end
local OEc,PEc,QEc
if#oEc>0 then
for REc,SEc in ipairs(nEc)do
local TEc=(bb.laneW and SEc.lane)and(zEc[tostring(SEc.lane)]or 0)or sEc
if SEc.hp>0 and SEc.prog>TEc+0.02 and SEc.prog>(OEc or 0)then
OEc,QEc=SEc.prog,bb.laneW and SEc.lane or nil
end
if SEc.hp>0 and SEc.fly and SEc.prog>tEc+0.02 then
PEc=true
end
end
end
local UEc= #oEc>0 and(bb.pressure or 0)>=sEc-0.08
return{covEnd=sEc,airEnd=tEc,leak=OEc,leakLane=QEc,covL=zEc,airLeak=PEc,push=UEc,units= #oEc}
end
