local LGc=1
if HGc then
LGc=0.15+0.85*(tonumber(HGc[math.min(gb.BINS,math.floor(KGc.prog*gb.BINS)+1)])or 0)
end
if IGc then
LGc=LGc*(IGc[tostring(KGc.lane)]or 1)
end
if DGc then
if DGc.leak and KGc.prog>=DGc.leak-0.01 and(not DGc.leakLane or tostring(KGc.lane)==DGc.leakLane)then
LGc=LGc+3
elseif DGc.push and KGc.prog>DGc.covEnd then
LGc=LGc+0.6
end
end
FGc=FGc+LGc
end
end
return FGc
end
