function bb.grifOpts(Ngd,Ogd,Pgd,Qgd,Rgd)
local Sgd=bb.grifS
if not(bb.grifOn()and Sgd and not Sgd.done and not Sgd.off)then
return
end
local Tgd=bb.grifNow
if not Tgd or Tgd.m~=Sgd.m then
return
end
local Ugd={}
for Vgd,Wgd in ipairs(Tgd.fodder)do
Ugd[Wgd]=true
end
for Xgd= #Ngd,1,-1 do
if Ngd[Xgd].m and Ugd[Ngd[Xgd].m]then
table.remove(Ngd,Xgd)
end
end
Sgd.more=false
if not bb.grifLong()then
if not Sgd.lateSaid then
Sgd.lateSaid=true
F.log(1,nHe[4790],string.format(nHe[4800],bb.GRIF_MIN_WAVES,gb.REINC_LEFT))
end
return
end
local Ygd=bb.depth and bb.depth.units>0 and bb.depth.covEnd or 1
if(bb.pressure or 0)>=math.min(O.dangerReach,Ygd*0.9)*0.8 or(bb.depth and bb.depth.leak)then
return
end
local Zgd=math.max(1,Tgd.need-Tgd.yen)
local _gd=(bb.info and tonumber(bb.info.waveSec))or 20
local ahd=math.max(1,tonumber(bb.incomeRate)or((((bb.coming and bb.coming[1]and bb.coming[1].reward)or 500)+(tonumber(bb.farmNow)or 0))/_gd))
local bhd=math.max(0,Zgd-Ogd)/ahd
local chd=(bb.teamDps or 0)/(1+U.clamp(tonumber(bb.buffLevel())or 0,0,2))/V.GRIF.need/(1+bhd/(6*_gd))
if chd<=0 then
return
end
local dhd=string.format(nHe[4801],U.fmt(Tgd.yen),U.fmt(Tgd.need))
for ehd,fhd in ipairs(Tgd.fodder)do
local ghd=fhd._stats
local hhd=ghd.id.Value
local ihd=V.rows(hhd)
local jhd=tonumber(ghd.upgrade.Value)or 0
local khd=ihd and ihd[jhd+1]
if khd and jhd<ihd.max and not((bb.upFail[fhd]or 0)>=3 and U.now()-(bb.upFailAt[fhd]or 0)<60)then
local lhd=1
pcall(function()
lhd=N.USC.calculate_upgrade_cost_multiplier(fhd,N.session())
end)
local mhd=khd.cost*lhd
Sgd.more=true
if Tgd.yen<Tgd.need then
table.insert(Ngd,{grif=true,cost=mhd,gain=chd*mhd,m=fhd,what=string.format(nHe[4802],V.name(hhd),jhd+1,dhd)})
end
end
end
if Tgd.yen>=Tgd.need or bb.fieldCount()>=bb.FIELD_MAX or bb.placePaused()then
return
end
for nhd,ohd in ipairs(Sgd.fodder)do
if#(Qgd[ohd.uuid]or{})<V.cap(ohd.u)and(bb.noSpot[ohd.uuid]or 0)<3 then
local phd=(tonumber(ohd.data.cost)or 0)*Pgd
Sgd.more=true
table.insert(Ngd,{place=true,grif=true,cost=phd,gain=chd*phd,e=setmetatable({_grif=true},{__index=ohd}),what=string.format(nHe[4803],V.name(ohd.id),dhd)})
end
end
end
function bb.grifEggGain(qhd,rhd)
local shd=bb.grifS
if not(bb.grifOn()and shd and not shd.done and not shd.off and bb.grifLong())then
return 0
end
local thd=bb.depth and bb.depth.units>0 and bb.depth.covEnd or 1
if(bb.pressure or 0)>=math.min(O.dangerReach,thd*0.9)*0.8 or(bb.depth and bb.depth.leak)then
return 0
end
local uhd=(bb.info and tonumber(bb.info.waveSec))or 20
local vhd=math.max(1,tonumber(bb.incomeRate)or((((bb.coming and bb.coming[1]and bb.coming[1].reward)or 500)+(tonumber(bb.farmNow)or 0))/uhd))
local whd=math.max(0,V.GRIF.need+(tonumber(qhd)or 0)-(tonumber(rhd)or 0))/vhd
local xhd=(bb.teamDps or 0)/(1+U.clamp(tonumber(bb.buffLevel())or 0,0,2))/V.GRIF.need/(1+whd/(6*uhd))
return math.max(0,xhd*(tonumber(qhd)or 0))
end
bb.GRIF_RESERVE,bb.GRIF_MIN_WAVES=2,30
function bb.grifLong()
if bb.infinite or(bb.info and bb.info.timeLimit)then
return true
end
local yhd=tonumber(bb.total)or 0
return yhd>=bb.GRIF_MIN_WAVES and yhd-(tonumber(bb.wave())or 0)>=gb.REINC_LEFT
end
function bb.grifCap(zhd,Ahd)
local Bhd=bb.grifS
if not(bb.grifOn()and Bhd and not Bhd.done and not Bhd.off and V.allyBuff(zhd.id)and V.sacFodder(zhd.id)and bb.grifLong())then
return Ahd
end
local Chd=0
for Dhd,Ehd in ipairs(bb.grifNow and bb.grifNow.fodder or{})do
local Fhd=Ehd._stats:FindFirstChild(nHe[2619])
if Fhd and Fhd.Value==zhd.uuid then
Chd=Chd+1
end
end
return math.min(Ahd,math.max(1,Ahd-bb.GRIF_RESERVE)+Chd)
end
function bb.grifTick()
if not bb.grifOn()then
bb.grifZone,bb.grifNow=nil,nil
return
end
local Ghd=bb.grifS
bb.grifNow=bb.grifScan()
local Hhd=bb.grifNow
if Hhd and ab.every(nHe[4804],5)then
F.status(nHe[4794],string.format(nHe[4805],U.fmt(Hhd.yen),U.fmt(Hhd.need)))
end
local Ihd=Ghd.cast
if not Ihd or Ghd.done then
return
end
local Jhd=U.now()
if not Ihd.counted then
if Jhd-Ihd.at<2 then
return
end
local Khd=0
for Lhd,Mhd in pairs(Ihd.units)do
if not(Lhd.Parent and Lhd.Parent.Name==nHe[4461])then
Khd=Khd+Mhd
end
end
if Khd<=0 then
if Jhd-Ihd.at>6 then
Ghd.cast=nil
end
return
end
Ihd.counted=true
Ghd.casts=Ghd.casts+1
Ghd.fed[Ihd.m]=(tonumber(Ghd.fed[Ihd.m])or 0)+Khd
F.log(1,nHe[4790],string.format(nHe[4806],U.fmt(Khd),U.fmt(Ghd.fed[Ihd.m]),U.fmt(V.GRIF.need),bb.grifAdds()and nHe[1151]or nHe[4807]))
if Ghd.fed[Ihd.m]<V.GRIF.need then
Ghd.cast=nil
end
return
end
if Jhd-Ihd.at<15 then
return
end
Ghd.cast=nil
if not Ihd.m.Parent then
return
end
if Ghd.casts>=2 and bb.grifAdds()then
P.grif.adds,P.grif.at=false,os.time()
pcall(F.saveSoon)
F.log(1,nHe[4790],string.format(nHe[4808],U.fmt(Ghd.fed[Ihd.m]),Ghd.casts,U.fmt(V.GRIF.need)))
Ghd.fed[Ihd.m]=0
else
Ghd.off,Ghd.offWhy,bb.grifZone,bb.grifNow=true,nHe[4809],nil,nil
F.log(1,nHe[4790],string.format(nHe[4810],U.fmt(Ghd.fed[Ihd.m])))
end
end
function bb.sacrificeOk(Nhd,Ohd)
local Phd=O.griffinSacrifice
if Phd==nHe[2358]then
return nil,nil,true
end
if Phd==nHe[2359]then
return false
end
local Qhd=bb.grifOn()
if Qhd and(bb.grifS.done or bb.grifS.off)then
if bb.grifS.done then
return false
end
Qhd=false
end
if not bb.infinite and bb.total and bb.wave()>=bb.total-2 then
return false
end
local Rhd,Shd=U.flat(Nhd:GetPivot().Position),tonumber(Ohd.range.Value)or 0
local Thd,Uhd,Vhd,Whd=0,{},0,{}
for Xhd,Yhd in ipairs(bb.mine or{})do
local Zhd=Yhd~=Nhd and Yhd:FindFirstChild(nHe[2304])
local _hd=Zhd and Zhd:FindFirstChild(nHe[2620])and Zhd.id.Value
if _hd and(U.flat(Yhd:GetPivot().Position)-Rhd).Magnitude<=Shd then
if V.sacFodder(_hd)then
Thd=Thd+1
local aid=Zhd:FindFirstChild(nHe[4487])and tonumber(Zhd.total_spent.Value)or 0
Vhd=Vhd+aid
Whd[Yhd]=aid
else
Uhd[V.name(_hd)]=true
end
end
end
if next(Uhd)then
bb.sacSaid=bb.sacSaid or{}
if not bb.sacSaid[Nhd]then
bb.sacSaid[Nhd]=true
local cid={}
for did in pairs(Uhd)do
table.insert(cid,did)
end
table.sort(cid)
F.log(1,nHe[4785],string.format(nHe[4811],V.name(Ohd.id.Value),table.concat(cid,nHe[2356])))
end
return false
end
if Thd==0 then
return false
end
if Qhd then
local eid=bb.grifS
if Nhd~=eid.m or eid.cast then
return false
end
local fid=bb.grifNow
local gid=bb.grifNeed(Nhd)
local hid=Vhd>=gid-1 or(bb.grifAdds()and fid~=nil and fid.m==Nhd and fid.maxed and not eid.more)
if not hid then
return false
end
eid.cast={m=Nhd,at=U.now(),units=Whd,yen=Vhd}
return true,string.format(nHe[4812],Thd,Thd==1 and nHe[1151]or nHe[2078],U.fmt(Vhd),U.fmt(gid))
end
return true,string.format(nHe[4813],Thd,Thd==1 and nHe[1151]or nHe[2078],U.fmt(Vhd))
end
function bb.aoeActive(iid)
