function bb.aoePoint(kid,lid)
local nid=U.flat(kid:GetPivot().Position)
local oid={}
for qid,rid in ipairs(bb.samples or{})do
if(U.flat(rid.pos)-nid).Magnitude<=lid*0.95 then
table.insert(oid,rid)
end
end
if#oid==0 then
return nil
end
local sid,tid,vid,wid=nil,-1,-1,0
for xid,yid in ipairs(oid)do
local zid,Aid=0,0
for Bid,Cid in ipairs(bb.enemies or{})do
local Did=Cid.pos and(U.flat(Cid.pos)-U.flat(yid.pos)).Magnitude or math.huge
if Did<=12 then
Aid=Aid+1
zid=zid+(1-Did/12*0.9)*(Cid.boss and 3 or 1)
end
end
if zid>tid+1e-6 or(math.abs(zid-tid)<=1e-6 and yid.prog>vid)then
sid,tid,vid,wid=yid,zid,yid.prog,Aid
end
end
if wid<=0 then
local Eid=type(P.maps[bb.mapKey()])==nHe[2232]and P.maps[bb.mapKey()].dens or nil
if type(Eid)==nHe[2232]and#Eid>0 then
local Fid= -1
for Gid,Hid in ipairs(oid)do
local Iid=tonumber(Eid[math.max(1,math.min(#Eid,math.floor(Hid.prog* #Eid)+1))])or 0
if Iid>Fid then
sid,Fid=Hid,Iid
end
end
else
sid=oid[math.ceil(#oid/2)]
end
end
return sid and sid.pos or nil,wid
end
