function bb.huntChoose(ald,bld)
bb.fhP=bb.fhP or 1
local cld=mb.floor()
local dld=(bb.pressure or 0)>=O.safeReach or(bb.depth and bb.depth.leak)
local eld=mb.weatherStrength(mb.weatherNow())
local fld=table.find(mb.CARD_PICKS,O.huntCards)and O.huntCards or nHe[1155]
local gld,hld,ild,jld
local kld={}
bb.fhFactors={}
for lld,mld in pairs(ald)do
local nld,pld=1,{}
for qld,rld in pairs(type(mld)==nHe[2232]and mld.effects or{})do
if type(rld)==nHe[2232]then
local sld=bb.rogueEffect(rld)
nld=nld*sld
table.insert(pld,bb.effectText(rld))
end
end
if type(mld)==nHe[2232]and mld.weather then
nld=nld*mb.weatherStrength(mld.weather)/math.max(0.05,eld)
end
if type(mld)==nHe[2232]and(mld.title or mld.name)then
bb.fhFactors[tostring(mld.title or mld.name):lower():gsub(nHe[4847],nHe[1151])]=nld
end
local tld=type(mld)==nHe[2232]and mb.cardGems(mld,bld)or 0
local uld=nld>=1 or(bb.fhP*nld>=cld and not dld)
local vld=math.log(math.max(0.05,nld))
local wld=vld*mb.STRENGTH_GEMS+(uld and tld or-1000)
local xld=mb.cardLuck(mld)
if fld==nHe[1153]and uld and xld>0 then
wld=2e6+xld*1e4+tld
elseif fld==nHe[2250]and uld then
wld=1e6+mb.cardPearls(mld,bld)*10+tld+vld
elseif fld==nHe[2805]then
wld=vld*1e6+tld
end
if not hld or wld>hld then
gld,hld,ild,jld=lld,wld,nld,tld
end
table.insert(kld,string.format(nHe[4848],tostring(lld),tostring(type(mld)==nHe[2232]and mld.title or nHe[2478]),(type(mld)==nHe[2232]and mld.weather)and(nHe[2953]..tostring(mld.weather)..nHe[2906])or nHe[1151],tostring(type(mld)==nHe[2232]and mld.option_type or nHe[2478]),nld,math.floor(tld+0.5),table.concat(pld,nHe[2877])))
end
return gld,ild,jld,kld,cld,dld,fld
end
