function bb.huntWeakText()
local cmd=type(P.hunt)==nHe[2232]and P.hunt.runs or{}
if#cmd<bb.HUNT_WEAK_RUNS then
return nil
end
local dmd,emd,fmd=0,0,{}
for gmd=1,bb.HUNT_WEAK_RUNS do
