end
dmd,emd=dmd+(tonumber(hmd.pearls)or 0),emd+(tonumber(hmd.sec)or 0)
table.insert(fmd,tonumber(hmd.wave)or 0)
end
if emd<=0 then
return nil
end
table.sort(fmd)
local imd=fmd[math.ceil(#fmd/2)]
local jmd=dmd/emd*60*(tonumber(O.pearlValue)or 0.35)
local kmd={string.format(nHe[4872],bb.HUNT_WEAK_RUNS,imd,jmd)}
local lmd
for mmd,nmd in ipairs(W.lastScored or{})do
if nmd.kind~=nHe[2255]and(tonumber(nmd.score)or 0)>0 then
lmd=nmd
