local Qmd=tostring(Pmd):gsub(nHe[4156],nHe[1151])
local Rmd,Smd=0,0
for Tmd,Umd in ipairs(bb.mine or{})do
local Vmd=Umd._stats.id.Value
if not V.isFarm(Vmd)then
local Wmd,Xmd=pcall(bb.liveDps,Umd,Vmd)
Xmd=Wmd and Xmd or 0
local Ymd=V.types(Vmd)
Rmd=Rmd+Xmd
if Ymd[Qmd]or Ymd[Qmd..nHe[2446]]then
Smd=Smd+Xmd
end
end
end
local Zmd=0
for _md,bnd in ipairs(bb.mine or{})do
if not V.isFarm(bnd._stats.id.Value)then
Zmd=Zmd+1
end
end
local cnd=Zmd/(Zmd+4)
return cnd*(Rmd>0 and Smd/Rmd or 0.5)+(1-cnd)*0.5
end
function bb.resistOf(dnd)
