function bb.rogueEffect(knd)
local lnd,mnd,nnd=knd.type,tonumber(knd.amount)or 0,tostring(knd.stat or nHe[1151])
if lnd==nHe[2787]then
return 1,math.abs(mnd)
end
if lnd==nHe[4280]or lnd==nHe[4285]or lnd==nHe[4281]then
if nnd==nHe[2677]then
return math.max(0.3,1+mnd),0
end
if nnd==nHe[2495]then
return math.max(0.5,1+mnd/2),0
end
if nnd:find(nHe[3035])then
return 1/math.max(0.3,1+mnd),0
end
return 1,0
end
if lnd==nHe[4879]then
if nnd==nHe[2677]then
return math.max(0.3,mnd),0
end
if nnd==nHe[2495]then
return math.max(0.5,1+(mnd-1)/2),0
end
if nnd:find(nHe[3035])then
return 1/math.max(0.3,mnd),0
end
return 1,0
end
if lnd==nHe[4287]then
