end
if lnd==nHe[4293]then
return 1/math.max(0.3,1+mnd),0
end
if lnd==nHe[4880]then
return math.max(0.2,1-bb.rogueShare(knd.damage_type)*(1-100/(100+mnd))),0
end
if lnd==nHe[4881]then
return 1+bb.rogueShare(knd.damage_type)*mnd,0
end
if lnd==nHe[4882]then
return math.max(0.5,1-mnd*0.5),0
end
if lnd==nHe[4883]then
return math.max(0.5,1-mnd*0.2),0
end
if lnd==nHe[4884]then
return 1+mnd*0.1,0
end
if lnd==nHe[4885]then
return 1/math.max(0.3,1+mnd*0.5),0
end
if lnd==nHe[4886]then
return math.max(0.5,1-mnd*0.1),0
end
if lnd==nHe[4288]then
return 1/math.max(0.3,1+mnd),0
end
if lnd==nHe[4294]then
return math.max(0.3,1-mnd*20),0
end
if lnd==nHe[4295]then
return math.max(0.5,1-mnd*0.03),0
end
if lnd==nHe[4887]then
