function bb.learn()
local qnd=bb.calRun and bb.calRun.potBy
if type(qnd)~=nHe[2232]then
return
end
pcall(bb.sampleHelpers,true)
local rnd={}
for snd,tnd in pairs(bb.ownDealt or{})do
if not V.isFarm(tnd.id)then
rnd[tnd.id]=(rnd[tnd.id]or 0)+(tonumber(tnd.v)or 0)
end
end
for und,vnd in pairs(bb.helperDealt or{})do
if vnd.owner and V.SUMMONER[vnd.owner]and not V.droneHelper(vnd)then
rnd[vnd.owner]=(rnd[vnd.owner]or 0)+(tonumber(vnd.v)or 0)
end
end
local wnd=type(bb.calRun.potExp)==nHe[2232]and bb.calRun.potExp or{}
local xnd,ynd=0,0
local znd={}
for And,Bnd in pairs(qnd)do
if Bnd>0 then
xnd,ynd=xnd+(rnd[And]or 0),ynd+Bnd
local Cnd=tonumber(wnd[And])or Bnd
if Cnd>0 then
table.insert(znd,{id=And,r=(rnd[And]or 0)/Cnd,w=Cnd})
end
end
end
if xnd<=0 or ynd<=0 then
return
end
table.sort(znd,function(Dnd,End)
return Dnd.r<End.r
end)
local function Fnd(Gnd)
local Hnd,Ind=0,0
for Jnd,Knd in ipairs(znd)do
if Knd.id~=Gnd then
Hnd=Hnd+Knd.w
end
end
if Hnd<=0 then
return nil
end
for Lnd,Mnd in ipairs(znd)do
if Mnd.id~=Gnd then
Ind=Ind+Mnd.w
if Ind>=Hnd/2 then
return Mnd.r
end
end
end
end
bb.lastEff={}
for Nnd,Ond in pairs(qnd)do
local Pnd=Fnd(Nnd)
if Ond>0 and Ond/ynd>0.02 and Pnd and Pnd>0 then
local Qnd=P.learn[Nnd]or{eff=1,n=0,v=6}
V.learnUp(Nnd,Qnd)
local Rnd=math.max(0.02,0.25*math.sqrt(30/(30+Qnd.n)))
local Snd=U.clamp(((rnd[Nnd]or 0)/Ond)/Pnd,0.2,6)
bb.lastEff[Nnd]=math.floor(Snd*1000+0.5)/1000
Qnd.eff=Qnd.eff+(Snd-Qnd.eff)*Rnd
Qnd.n=Qnd.n+1
P.learn[Nnd]=Qnd
end
end
local Tnd=V.mapKey((bb.info and bb.info.map)or(bb.ld and bb.ld.map),(bb.info and bb.info.mapSig)or V.mapSig(bb.ld))
if Tnd and next(bb.lastEff)then
P.mapLearn=type(P.mapLearn)==nHe[2232]and P.mapLearn or{}
local Und=type(P.mapLearn[Tnd])==nHe[2232]and P.mapLearn[Tnd]or{}
for Vnd,Wnd in pairs(bb.lastEff)do
local Xnd=type(Und[Vnd])==nHe[2232]and Und[Vnd]or{eff=Wnd,n=0,v=6}
if(tonumber(Xnd.v)or 0)<4 then
Xnd.eff,Xnd.v=(tonumber(Xnd.eff)or Wnd)*V.secRescale(Vnd),4
end
if(tonumber(Xnd.v)or 0)<5 then
Xnd.eff,Xnd.v=(tonumber(Xnd.eff)or Wnd)*(V.sumRescale(Vnd)or 1),5
end
if(tonumber(Xnd.v)or 0)<6 then
Xnd.eff,Xnd.v=(tonumber(Xnd.eff)or Wnd)*(1-(V.SUMMONER[Vnd]and V.SUMMONER[Vnd].droneShare or 0)),6
end
local Ynd=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(Xnd.n)or 0))))
Xnd.eff=(tonumber(Xnd.n)or 0)==0 and Wnd or((tonumber(Xnd.eff)or Wnd)+(Wnd-(tonumber(Xnd.eff)or Wnd))*Ynd)
Xnd.n=(tonumber(Xnd.n)or 0)+1
Und[Vnd]=Xnd
end
Und._at=os.time()
P.mapLearn[Tnd]=Und
if U.count(P.mapLearn)>80 then
local Znd,_nd
for aod,bod in pairs(P.mapLearn)do
if not _nd or(tonumber(bod._at)or 0)<_nd then
Znd,_nd=aod,tonumber(bod._at)or 0
end
end
P.mapLearn[Znd]=nil
end
end
end
function bb.randomTeam()
