local function god(hod,iod,jod)
local kod=hod and dod[hod]
if kod and N.Units[kod.unit_id]and not fod[hod]then
fod[hod]=true
table.insert(eod,{slot=jod or 99,uuid=hod,u=kod,id=kod.unit_id,data=N.Units[kod.unit_id],hand=iod})
