local Ltd=bb.bestRate or 0
if Ktd or Ltd<=0 then
return
end
local Mtd=bb.wave()
local Ntd=math.max(0,(bb.total or 30)-Mtd)
local Otd=bb.mergePlan
local Ptd=bb.airLow()
local Qtd,Rtd,Std
for Ttd,Utd in ipairs(bb.mine)do
local Vtd=Utd._stats
local Wtd=Vtd.id.Value
local Xtd=N.Units[Wtd]
local Ytd=Vtd:FindFirstChild(nHe[4487])and tonumber(Vtd.total_spent.Value)or 0
if Xtd and not Xtd.unsellable and Ytd>0 and not V.allyBuff(Wtd)and not V.idol(Wtd)and not(Otd and Otd.id==Wtd)then
local Ztd,_td
if V.isFarm(Wtd)then
local aud=Vtd:FindFirstChild(nHe[2352])and tonumber(Vtd.farm_amount.Value)or 0
local bud=aud*Ntd
if Ytd>bud*1.2 then
Ztd=(Ytd-bud)*Ltd
_td=string.format(nHe[4975],U.fmt(bud),U.fmt(Ytd))
end
elseif Mtd>=10 and Ntd>2 and Ytd>=5000 and(bb.upRate[Utd]or 0)<Ltd/3 and bb.progressAt(Utd:GetPivot().Position)<0.8 and not(Ptd and bb.canAir(Utd))then
local cud,dud=pcall(bb.liveDps,Utd,Wtd)
dud=cud and dud or math.huge
if Ytd*Ltd>3*dud and dud<0.1*(bb.teamDps or 0)then
Ztd=Ytd*Ltd-dud
_td=string.format(nHe[4976],U.fmt(Ytd))
end
end
if Ztd and(not Rtd or Ztd>Rtd)then
Qtd,Rtd,Std=Utd,Ztd,_td
end
end
end
if not Qtd then
return
end
bb.spellBusy=true
task.spawn(function()
local eud=V.name(Qtd._stats.id.Value)
local fud=F.request(nHe[4967],nHe[4968],Htd,Qtd)
task.wait(1.5)
if fud and(N.session().ingame_spells or{})[Htd]~=nHe[4961]then
bb.refunds=(bb.refunds or 0)+1
F.log(1,nHe[4947],string.format(nHe[4977],eud,Std))
F.status(nHe[4830],nHe[4978]..eud)
else
F.backoff(nHe[4967],15)
F.log(2,nHe[4947],nHe[4979]..eud)
end
bb.spellBusy=false
end)
end
bb.BASE_WIN,bb.BASE_MARGIN,bb.BASE_SOON,bb.BASE_END=10,1.3,45,0.97
function bb.baseVerdict(gud,hud)
local iud=(hud.t or 0)-(gud.t or 0)
if iud<bb.BASE_WIN-1 then
return false
end
local jud=((tonumber(gud.base)or 0)-(tonumber(hud.base)or 0))/iud
if jud<=0 or(tonumber(hud.base)or 0)<=0 then
return false
end
local kud=hud.base/jud
local lud,mud=0,0
local nud,oud=gud.foes or{},hud.foes or{}
for pud,qud in pairs(oud)do
if qud.prog>=bb.BASE_END then
lud=lud+qud.hp
local rud=nud[pud]
if rud then
mud=mud+math.max(0,rud.hp-qud.hp)
end
end
end
for sud,tud in pairs(nud)do
if tud.prog>=bb.BASE_END and not oud[sud]then
mud=mud+tud.hp
end
end
if lud<=0 then
return false
end
local uud=mud/iud
local vud=uud>0 and lud/uud or math.huge
local wud={baseTime=kud,loss=jud,atEnd=lud,rate=uud,killTime=vud}
return kud<bb.BASE_SOON and vud>kud*bb.BASE_MARGIN,wud
end
