if bvd and cvd and not V.isFarm(bvd.Value)and not V.allyBuff(bvd.Value)then
local dvd,evd=U.flat(_ud:GetPivot().Position),cvd.Value
if(not Wud.fly or bb.canAir(_ud))and(dvd-Yud).Magnitude>evd then
for fvd,gvd in ipairs(bb.samples or{})do
if gvd.prog>Wud.prog and(U.flat(gvd.pos)-dvd).Magnitude<=evd then
Xud=Xud+1
break
end
end
end
end
end
return Xud
end
function bb.leakStep(hvd)
if not hvd then
if bb.kind~=nHe[2258]or bb.bailed or O.bailOut==false or bb.random or bb.infinite then
return
end
end
local ivd=tostring(P.dg.room and P.dg.room.seed)
P.dg.bails=type(P.dg.bails)==nHe[2232]and P.dg.bails or{}
if not hvd and(tonumber(P.dg.bails[ivd])or 0)>=bb.BAIL_MAX then
return
end
local jvd=workspace:FindFirstChild(nHe[4992])and workspace._BASES:FindFirstChild(nHe[4446])
local kvd=jvd and jvd:FindFirstChild(nHe[4692])and jvd.base:FindFirstChild(nHe[4693])
local lvd=kvd and kvd:FindFirstChildOfClass(nHe[2636])
if not lvd or lvd.Health<=0 then
return
end
local mvd=(bb.info and tonumber(bb.info.baseRel))or gb.PRIOR.baseRel
local nvd=U.now()
bb.leakTrack=bb.leakTrack or{}
local ovd=bb.leakTrack
local pvd,qvd={},nil
for rvd,svd in ipairs(bb.enemies or{})do
if svd.m then
pvd[svd.m]=true
local tvd,uvd=tonumber(svd.hp)or 0,tonumber(svd.prog)or 0
local vvd=ovd[svd.m]
if not vvd then
ovd[svd.m]={t=nvd,hp=tvd,prog=uvd}
else
if nvd-vvd.t>=bb.LEAK_WIN then
vvd.pace,vvd.net=(uvd-vvd.prog)/(nvd-vvd.t),(vvd.hp-tvd)/(nvd-vvd.t)
vvd.t,vvd.hp,vvd.prog=nvd,tvd,uvd
end
if vvd.pace and vvd.pace>0 and tvd>0 then
local wvd=(1-uvd)/vvd.pace
local xvd=math.max(0,vvd.net or 0)
local yvd=tvd-xvd*wvd
if yvd>0 and wvd<=bb.LEAK_SOON and wvd>=bb.LEAK_MIN then
local zvd=svd.m:FindFirstChildOfClass(nHe[2636])
local Avd=lvd.Health/math.max(1,mvd*(zvd and zvd.MaxHealth or tvd))
local Bvd=xvd>0 and yvd/xvd or math.huge
if Bvd>Avd*bb.LEAK_MARGIN and(wvd<=bb.LEAK_AHEAD or bb.leakAhead(svd)==0)and(not qvd or wvd<qvd.left)then
qvd={left=wvd,arriving=yvd,net=xvd,baseTime=Avd,hp=tvd}
end
end
end
end
end
end
for Cvd in pairs(ovd)do
if not pvd[Cvd]then
ovd[Cvd]=nil
end
end
if hvd then
return qvd~=nil,qvd
end
if not qvd then
return
end
bb.bailNote(ivd,nHe[4986])
F.log(1,nHe[2913],string.format(nHe[4995],bb.wave(),tonumber(bb.total)or 0,math.floor(qvd.left+0.5),U.fmt(qvd.hp),U.fmt(qvd.arriving),U.fmt(qvd.net),qvd.baseTime))
pcall(F.saveNow)
bb.toLobby(nHe[4994])
end
