function bb.allPast(Dvd)
local Evd={}
for Fvd,Gvd in ipairs(bb.mine or{})do
local Hvd=Gvd._stats
local Ivd=Hvd.id.Value
if not V.isFarm(Ivd)and not V.allyBuff(Ivd)and Hvd:FindFirstChild(nHe[2495])then
local Jvd=tonumber(Hvd.range.Value)or 0
local Kvd=bb.coverMax[Gvd]
if not(Kvd and Kvd.r==Jvd)then
local Lvd,Mvd=U.flat(Gvd:GetPivot().Position),-1
for Nvd,Ovd in ipairs(bb.samples or{})do
if Ovd.prog>Mvd and(U.flat(Ovd.pos)-Lvd).Magnitude<=Jvd then
Mvd=Ovd.prog
end
end
Kvd={r=Jvd,far=Mvd}
bb.coverMax[Gvd]=Kvd
end
table.insert(Evd,{far=Kvd.far,air=bb.canAir(Gvd)})
end
end
if#Evd==0 then
