_vd={m=Wvd.m,id=Vvd,name=cwd,wave=bb.wave(),t0=U.now(),max=bwd,low=1,assassin=Tvd.assassin,beatAt=tonumber(Tvd.beatAt)or 0.5,walk=Tvd.walk}
