if#(bb.enemies or{})==1 and bb.total and bb.wave()>=bb.total then
_vd.aloneT=_vd.aloneT or U.now()
_vd.alone=math.max(_vd.alone or 0,U.now()-_vd.aloneT)
else
_vd.aloneT=nil
end
end
