bb.mergeIds={}
function bb.mergeScan()
bb.mergePlan,bb.mergeIds=nil,{}
if not bb.random then
return
end
local wAd=N.session()
local xAd=false
bb.cloneCard=false
for yAd,zAd in pairs((wAd and wAd.ingame_spells)or{})do
if zAd==nHe[4959]then
xAd=true
elseif zAd==nHe[5023]then
bb.cloneCard=true
end
end
local AAd={}
local BAd=P.fh.noMerge or{}
for CAd,DAd in ipairs(bb.mine or{})do
local EAd=DAd._stats
local FAd=EAd.id.Value
if not V.isFarm(FAd)and not V.allyBuff(FAd)and not V.idol(FAd)and EAd:FindFirstChild(nHe[2629])and(BAd[FAd]or 0)<2 then
local GAd,HAd=pcall(bb.liveDps,DAd,FAd)
AAd[FAd]=AAd[FAd]or{}
table.insert(AAd[FAd],{m=DAd,lvl=EAd.upgrade.Value,max=EAd.max_upgrade.Value,dps=GAd and HAd or 0})
end
end
local IAd={}
for JAd,KAd in ipairs(bb.team or{})do
if KAd.hand then
IAd[KAd.id]=true
end
end
local LAd={}
for MAd,NAd in pairs(AAd)do
table.sort(NAd,function(OAd,PAd)
if OAd.dps~=PAd.dps then
return OAd.dps>PAd.dps
end
return OAd.lvl>PAd.lvl
end)
table.insert(LAd,{id=MAd,dps=NAd[1].dps*bb.airBoost(NAd[1].m)*bb.reach(NAd[1].m)})
end
table.sort(LAd,function(QAd,RAd)
return QAd.dps>RAd.dps
end)
for SAd=1,math.min(3,#LAd)do
bb.mergeIds[LAd[SAd].id]=true
end
local TAd
for UAd,VAd in pairs(AAd)do
local WAd=table.clone(VAd)
table.sort(WAd,function(XAd,YAd)
if XAd.lvl~=YAd.lvl then
return XAd.lvl<YAd.lvl
end
return XAd.dps<YAd.dps
end)
for ZAd,_Ad in ipairs(WAd)do
if _Ad.m==bb.freshM and ZAd>1 then
table.remove(WAd,ZAd)
table.insert(WAd,1,_Ad)
break
end
end
local aBd,bBd,cBd,dBd
for eBd,fBd in ipairs(WAd)do
local gBd,hBd=U.flat(fBd.m:GetPivot().Position),fBd.m._stats.range.Value
local iBd,jBd,kBd=0,0,nil
for lBd,mBd in ipairs(VAd)do
if mBd~=fBd and(U.flat(mBd.m:GetPivot().Position)-gBd).Magnitude<=hBd then
iBd,jBd=iBd+mBd.dps,jBd+1
if not kBd or mBd.dps>kBd.dps then
kBd=mBd
end
end
end
if jBd>0 then
aBd,bBd,cBd,dBd=fBd,iBd,jBd,kBd
break
end
end
dBd=dBd or VAd[1]
local nBd=dBd.dps*bb.airBoost(dBd.m)*bb.reach(dBd.m)*(UAd==bb.planId and 2 or 1)
if(bb.mergeIds[UAd]or UAd==bb.planId)and(aBd or IAd[UAd])and(not TAd or nBd>TAd.score)then
TAd={id=UAd,top=dBd,fresh=aBd,near=bBd or 0,n=cBd or 0,coming=IAd[UAd],score=nBd}
end
end
bb.planId,bb.freshM=TAd and TAd.id,TAd and TAd.fresh and TAd.fresh.m
bb.mergeHeldAt=(xAd and TAd and TAd.fresh)and(bb.mergeHeldAt or bb.wave())or nil
if not TAd then
return F.status(nHe[4926],nHe[5024])
end
local oBd,pBd=bb.wave(),(bb.total or 30)-bb.wave()
local qBd=(bb.pressure or 0)>=math.min(O.dangerReach,((bb.depth and bb.depth.units>0 and bb.depth.covEnd)or 1)*0.9)
local rBd=TAd.fresh
local sBd=not qBd and pBd>3
TAd.waits=rBd and rBd.lvl<=TAd.top.lvl and TAd.top.lvl<TAd.top.max and sBd or false
local tBd=(not rBd or rBd.lvl>=TAd.top.lvl)and TAd.coming and sBd
local uBd=bb.cloneCard and TAd.top.lvl>=TAd.top.max and sBd
local vBd=rBd and rBd.lvl>TAd.top.lvl and TAd.near<0.3*rBd.dps
TAd.ready=xAd and rBd~=nil and not vBd and(not(TAd.waits or tBd or uBd)or oBd-(bb.mergeHeldAt or oBd)>=5)
bb.holdNoCardAt=(TAd.waits and not xAd)and(bb.holdNoCardAt or oBd)or nil
TAd.hold=TAd.waits and(xAd or oBd-(bb.holdNoCardAt or oBd)<4)
bb.mergePlan=TAd
F.status(nHe[4926],rBd and string.format(nHe[5025],V.name(TAd.id),TAd.n,TAd.n==1 and nHe[5026]or nHe[5027],rBd.lvl,TAd.ready and nHe[5028]or(xAd and nHe[5029]or nHe[5030]))or string.format(nHe[5031],V.name(TAd.id)))
end
function bb.mergeHold(wBd)
local xBd=bb.mergePlan
return xBd and xBd.hold and xBd.fresh and xBd.fresh.m==wBd or false
end
function bb.mergeBoost(yBd)
