if PBd>0 and OBd<0.1*PBd then
P.fh.noMerge[NBd]=(P.fh.noMerge[NBd]or 0)+1
elseif PBd>0 and OBd>=0.5*PBd then
P.fh.noMerge[NBd]=nil
end
F.log(1,nHe[4947],string.format(nHe[5032],V.name(HBd._stats.id.Value),U.fmt(IBd.own),U.fmt(KBd),IBd.lvl,U.fmt(IBd.near),U.fmt(LBd),IBd.top))
end)
