for ZBd,_Bd in ipairs(WBd)do
local aCd,bCd=U.flat(_Bd:GetPivot().Position),_Bd._stats.range.Value
local cCd,dCd=0,0
for eCd,fCd in ipairs(WBd)do
if fCd~=_Bd and(U.flat(fCd:GetPivot().Position)-aCd).Magnitude<=bCd then
cCd,dCd=cCd+(tonumber(fCd._stats.farm_amount.Value)or 0),dCd+1
