function bb.trainCount()
local DDd=P.train.on
if not(DDd and bb.trainee)then
return
end
local EDd=0
for FDd,GDd in ipairs(bb.mine)do
local HDd=GDd._stats
local IDd=HDd:FindFirstChild(nHe[2619])and HDd.uuid.Value
local JDd=IDd==bb.trainee and HDd:FindFirstChild(DDd.what==nHe[2896]and nHe[5055]or nHe[2632])
if JDd then
EDd=EDd+(tonumber(JDd.Value)or 0)
end
end
bb.trainTk=math.max(bb.trainTk or 0,EDd)
F.status(nHe[3536],string.format(nHe[5056],V.name(DDd.id),bb.trainTk,DDd.what,U.fmt(DDd.have+(DDd.got or 0)+bb.trainTk),U.fmt(DDd.need)))
end
function bb.trainDone(KDd,LDd)
local MDd=P.train.on
if not(MDd and bb.trainee)then
return
end
bb.trainCount()
local NDd=bb.trainTk or 0
MDd.got=(MDd.got or 0)+NDd
local ODd=P.trainSim[KDd]and tonumber(P.trainSim[KDd].tk)
if not bb.joinedMid then
local PDd=P.train.real[KDd]or{n=0,sum=0}
PDd.n,PDd.sum=PDd.n+1,PDd.sum+NDd
P.train.real[KDd]=PDd
if ODd and ODd>0 then
local QDd=P.train.cal
QDd.real,QDd.sim,QDd.n=(QDd.real or 0)+NDd,(QDd.sim or 0)+ODd,(QDd.n or 0)+1
end
end
table.insert(P.train.log,1,{key=KDd,got=NDd,won=LDd,at=os.time()})
while#P.train.log>20 do
table.remove(P.train.log)
end
F.log(1,nHe[3529],string.format(nHe[5057],V.name(MDd.id),NDd,MDd.what,LDd and nHe[3010]or nHe[3011],ODd and string.format(nHe[5058],ODd)or nHe[1151],U.fmt(ib.realHave(MDd)),U.fmt(MDd.need)))
if not LDd then
P.train.bad[KDd]=os.time()+3600
F.log(1,nHe[3529],nHe[5059])
end
end
