bb.SKIP_LOOK={every=2,upTo=20}
function bb.skipSafe()
if bb.noBuy or bb.trialId or bb.stopping or bb.finished then
return false,nHe[5060]
end
local TDd,UDd=bb.wave(),tonumber(bb.total)or 0
if UDd>0 and TDd>=UDd and not bb.infinite then
return false,nHe[5061]
end
if#(bb.mine or{})==0 then
return false,nHe[5062]
end
if bb.depth and bb.depth.leak then
return false,nHe[5063]
end
for VDd,WDd in ipairs(bb.enemies or{})do
if WDd.boss then
return false,nHe[5064]
end
end
local XDd=(bb.depth and(bb.depth.units or 0)>0 and tonumber(bb.depth.covEnd))or 1
local YDd=tonumber(bb.pressure)or 0
